def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        match = re.search(r"<([^<>]*)>", value)
        email = (match.group(1) if match else value).strip().lower()

        if email.count("@") != 1:
            return ""

        local, domain = email.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return f"{local}@{domain}"

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        phone = re.sub(r"[^0-9]", "", value)
        if len(phone) == 11 and phone.startswith("1"):
            phone = phone[1:]
        if len(phone) != 10 or phone[0] in "01":
            return ""
        return phone

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"[0-9]{5}-[0-9]{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"[0-9]{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"[0-9]{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        return value.title() if value.isupper() or value.islower() else value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    normalized = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        normalized.append({
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
            "opted_out": row["opted_out"].strip().lower()
                         in {"y", "yes", "true", "1"},
            "updated": parse_updated(row["updated"]),
            "_index": index,
        })

    # Union-find computes transitive groups without matching empty identifiers.
    parent = list(range(len(normalized)))
    size = [1] * len(normalized)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i, j):
        a, b = find(i), find(j)
        if a == b:
            return
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]

    email_owner = {}
    phone_name_owner = {}

    for i, row in enumerate(normalized):
        if row["email"]:
            email = row["email"]
            if email in email_owner:
                union(i, email_owner[email])
            else:
                email_owner[email] = i

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, row in enumerate(normalized):
        groups.setdefault(find(i), []).append(row)

    # Rows were visited in input order, so each group's first row is its earliest.
    ordered_groups = sorted(
        groups.values(), key=lambda group: group[0]["_index"]
    )

    output = []
    fields = ("first_name", "last_name", "zip", "email", "phone", "source")

    for group in ordered_groups:
        ranked = sorted(
            group,
            key=lambda row: (
                row["source"] == "manual",
                row["updated"],
                -row["_index"],
            ),
            reverse=True,
        )

        person = {
            field: next((row[field] for row in ranked if row[field]), "")
            for field in fields
        }

        tags = set()
        for row in group:
            tags.update(row["tags"])

        person["tags"] = ";".join(sorted(tags))
        person["opted_out"] = "Y" if any(row["opted_out"] for row in group) else "N"
        person["updated"] = max(row["updated"] for row in group).date().isoformat()
        output.append(person)

    # Opted-out people remain in the output with opted_out="Y";
    # callers must exclude them from email sends.
    return output
